import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { MarcheService } from '../../services/marche.service';
import { Marche, FiltreRecherche } from '../../models/marche.model';

@Component({
  selector: 'app-marche-list',
  templateUrl: './marche-list.component.html',
  styleUrls: ['./marche-list.component.scss']
})
export class MarcheListComponent implements OnInit {
  marches: Marche[] = [];
  isLoading = false;

  constructor(private marcheService: MarcheService, private router: Router) {}

  ngOnInit(): void { this.loadMarches(); }

  loadMarches(): void {
    this.isLoading = true;
    this.marcheService.getAllMarches().subscribe({
      next: (data) => { this.marches = data; this.isLoading = false; },
      error: (error) => { this.isLoading = false; console.error(error); }
    });
  }

  rechercher(filtres: FiltreRecherche): void {
    this.isLoading = true;
    this.marcheService.rechercherMarches(filtres).subscribe({
      next: (data) => { this.marches = data; this.isLoading = false; },
      error: (error) => { this.isLoading = false; console.error(error); }
    });
  }

  navigateToCreate(): void { this.router.navigate(['/marches/nouveau']); }
  editMarche(id: number): void { this.router.navigate([`/marches/editer/${id}`]); }
  deleteMarche(id: number): void {
    if (confirm('Supprimer ce marché ?')) {
      this.marcheService.deleteMarche(id).subscribe({
        next: () => this.loadMarches(),
        error: (error) => console.error(error)
      });
    }
  }
  refresh(): void { this.loadMarches(); }
  voirDetails(id: number): void { this.router.navigate(['/marches/details', id]); }
}
<div class="marche-list-container">
  <div class="header-actions">
    <h2>📋 Gestion des Marchés</h2>
    <div><button class="btn btn-refresh" (click)="refresh()">🔄</button><button class="btn btn-primary" (click)="navigateToCreate()">➕ Nouveau</button></div>
  </div>
  <app-recherche-marche (search)="rechercher($event)"></app-recherche-marche>
  <div class="table-container">
    <div *ngIf="isLoading" class="loading-spinner">⏳ Chargement...</div>
    <table class="table" *ngIf="!isLoading && marches.length > 0; else noData">
      <thead><tr><th>#</th><th>Référence</th><th>Objet</th><th>Statut</th><th>Montant</th><th>Région</th><th>Date</th><th>Actions</th></tr></thead>
      <tbody>
        <tr *ngFor="let marche of marches; let i = index">
          <td>{{ i + 1 }}</td>
          <td><strong>{{ marche.reference }}</strong></td>
          <td>{{ marche.objet }}</td>
          <td><span class="badge" [class.badge-success]="marche.statut === 'ACTIF'" [class.badge-warning]="marche.statut === 'EN_ATTENTE'" [class.badge-secondary]="marche.statut === 'ARCHIVE'">{{ marche.statut }}</span></td>
          <td>{{ marche.montant | number:'1.0-0' }} FCFA</td>
          <td>{{ marche.region || '-' }}</td>
          <td>{{ marche.dateCreation | date:'dd/MM/yyyy' }}</td>
          <td><button class="btn btn-sm btn-info" (click)="voirDetails(marche.id!)">👁️</button><button class="btn btn-sm btn-info" (click)="editMarche(marche.id!)">✏️</button><button class="btn btn-sm btn-danger" (click)="deleteMarche(marche.id!)">🗑️</button></td>
        </tr>
      </tbody>
    </table>
    <ng-template #noData><div class="empty-state"><p>📭 Aucun marché</p><button class="btn btn-primary" (click)="navigateToCreate()">Créer</button></div></ng-template>
  </div>
</div>
